#!/usr/bin/env python3
"""A tiny practice server on 127.0.0.1:8001.

/            echo the request back as JSON
/status/N    reply with status code N
/old         301 redirect to /new, which 302-redirects to /
/login       set a session cookie
/delay/N     wait N seconds, then reply
"""
import json
import time
from http.server import BaseHTTPRequestHandler, HTTPServer


class Echo(BaseHTTPRequestHandler):
    def reply(self, code, data, extra=()):
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        for name, value in extra:
            self.send_header(name, value)
        self.end_headers()
        self.wfile.write(data)

    def handle_any(self):
        length = int(self.headers.get("Content-Length", 0))
        body = self.rfile.read(length).decode("utf-8", "replace")
        path = self.path.split("?")[0]
        if path == "/old":
            return self.reply(301, b"", [("Location", "/new")])
        if path == "/new":
            return self.reply(302, b"", [("Location", "/")])
        if path.startswith("/status/"):
            code = int(path.rsplit("/", 1)[1])
            return self.reply(code, json.dumps({"status": code}).encode())
        if path.startswith("/delay/"):
            time.sleep(float(path.rsplit("/", 1)[1]))
        extra = []
        if path == "/login":
            extra.append(("Set-Cookie", "session=abc123; Path=/; HttpOnly"))
        seen = {
            "method": self.command,
            "path": self.path,
            "headers": dict(self.headers),
            "body": body,
        }
        self.reply(200, json.dumps(seen, indent=2).encode(), extra)

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = handle_any
    do_HEAD = handle_any


if __name__ == "__main__":
    print("echo server on http://127.0.0.1:8001 (Ctrl+C to stop)")
    HTTPServer(("127.0.0.1", 8001), Echo).serve_forever()

